import{_ as n,c as o,o as a,ah as t}from"./chunks/framework.DGDRXwgj.js";const g=JSON.parse('{"title":"Installing Seven Elements","description":"","frontmatter":{"prev":false,"next":false},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":1761055333000}'),r={name:"guide/installation.md"};function i(s,e,l,h,d,m){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="installing-seven-elements" tabindex="-1">Installing Seven Elements <a class="header-anchor" href="#installing-seven-elements" aria-label="Permalink to “Installing Seven Elements”">​</a></h1><p>This page will guide you on installing the Seven Elements mod depending on your mod loader.</p><h2 id="on-fabric" tabindex="-1">On Fabric <a class="header-anchor" href="#on-fabric" aria-label="Permalink to “On Fabric”">​</a></h2><p>When adding the mod on Fabric, simply grab the mod from <a href="https://modrinth.com/mod/seven-elements">Modrinth</a> or <a href="https://www.curseforge.com/minecraft/mc-mods/seven-elements">CurseForge</a>, install <a href="https://modrinth.com/mod/fabric-api">Fabric API</a> and <a href="https://modrinth.com/mod/cloth-config">Cloth Config</a> if you haven&#39;t yet, <a href="https://modrinth.com/mod/modmenu">Modmenu</a> to edit the config (this is optional!) and you&#39;re all set!</p><h2 id="on-forge-via-sinytra-connector" tabindex="-1">On Forge (via Sinytra Connector) <a class="header-anchor" href="#on-forge-via-sinytra-connector" aria-label="Permalink to “On Forge (via Sinytra Connector)”">​</a></h2><p>Here, we explain how to get Seven Elements on Forge via Sinytra Connector, which only works for the 1.20.1-LTS version. Sinytra Connector is the only way (as of now) to run Seven Elements on Forge. <strong>Any other versions</strong> of Seven Elements will <strong>not</strong> run on Forge and are not planned to be ported.</p><h3 id="downloading-the-mod" tabindex="-1">Downloading the mod <a class="header-anchor" href="#downloading-the-mod" aria-label="Permalink to “Downloading the mod”">​</a></h3><p>Like Fabric, simply grab the mod from <a href="https://modrinth.com/mod/seven-elements">Modrinth</a> or <a href="https://www.curseforge.com/minecraft/mc-mods/seven-elements">CurseForge</a>.</p><p><strong>Ensure</strong> that you grab the <strong>LTS</strong> version, which can be seen in the version number, i.e. &quot;1.0.3-LTS.1&quot;. Lower versions will <strong>not work</strong> with Sinytra Connector and will result in a crash.</p><p>Finally, install Sinytra&#39;s <a href="https://modrinth.com/mod/forgified-fabric-api">Forgified Fabric API</a> and <a href="https://modrinth.com/mod/connector">Sinytra Connector</a>, as well as <a href="https://modrinth.com/mod/cloth-config">Cloth Config</a> (the Forge version) if you don&#39;t have it yet.</p><h3 id="downloading-mixinextras-forge" tabindex="-1">Downloading MixinExtras Forge <a class="header-anchor" href="#downloading-mixinextras-forge" aria-label="Permalink to “Downloading MixinExtras Forge”">​</a></h3><p>Now, here comes the <em>somewhat</em> hard part.</p><p>Since Forge 1.20.1 does not have native support for <a href="https://github.com/LlamaLad7/MixinExtras" target="_blank" rel="noreferrer">MixinExtras</a> v0.5.0, you will have to download it directly and add it to your mods folder.</p><p>You can grab MixinExtras v0.5.0 from its official Maven Central repository link, which you can access through this link: <a href="https://mvnrepository.com/artifact/io.github.llamalad7/mixinextras-forge" target="_blank" rel="noreferrer">https://mvnrepository.com/artifact/io.github.llamalad7/mixinextras-forge</a></p><p>Alternatively, you can use this link to directly download the .jar file: <a href="https://repo1.maven.org/maven2/io/github/llamalad7/mixinextras-forge/0.5.0/mixinextras-forge-0.5.0.jar" target="_blank" rel="noreferrer">https://repo1.maven.org/maven2/io/github/llamalad7/mixinextras-forge/0.5.0/mixinextras-forge-0.5.0.jar</a></p><p>Once you&#39;ve obtained the <code>mixinextras-forge-0.5.0.jar</code> file, simply add it to your mods folder and Seven Elements should be able to run.</p><h2 id="on-neoforge-via-sinytra-connector" tabindex="-1">On NeoForge (via Sinytra Connector) <a class="header-anchor" href="#on-neoforge-via-sinytra-connector" aria-label="Permalink to “On NeoForge (via Sinytra Connector)”">​</a></h2><p>Unfortunately, Seven Elements cannot run on NeoForge <em>yet</em>. This is discussed in greater detail in <a href="https://github.com/xrickastley/SevenElements/issues/3#issuecomment-3421916749" target="_blank" rel="noreferrer">Seven Elements Issue #3</a>.</p>',18)])])}const f=n(r,[["render",i]]);export{g as __pageData,f as default};
